// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AdImpression) predicate.AdImpression {
	return predicate.AdImpression(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AdImpression) predicate.AdImpression {
	return predicate.AdImpression(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AdImpression) predicate.AdImpression {
	return predicate.AdImpression(sql.NotPredicates(p))
}
